package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
	SKU         string  `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// sanitizeCategory performs basic validation on category input
func sanitizeCategory(cat string) string {
	// Remove null bytes and trim whitespace
	cat = strings.ReplaceAll(cat, "\x00", "")
	cat = strings.TrimSpace(cat)
	if len(cat) > 100 {
		cat = cat[:100]
	}
	return cat
}

// buildProductQuery constructs the search query with optional filters
func buildProductQuery(category, sortField string, minPrice, maxPrice float64) string {
	baseQuery := "SELECT id, name, description, price, sku FROM products WHERE active = true"

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = '%s'", sanitizeCategory(category))
	}

	if minPrice > 0 {
		baseQuery += fmt.Sprintf(" AND price >= %.2f", minPrice)
	}
	if maxPrice > 0 {
		baseQuery += fmt.Sprintf(" AND price <= %.2f", maxPrice)
	}

	// Sort field validation - only allow known columns
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if allowedSorts[sortField] {
		baseQuery += " ORDER BY " + sortField
	} else {
		baseQuery += " ORDER BY name"
	}

	baseQuery += " LIMIT 50"
	return baseQuery
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")

	var minPrice, maxPrice float64
	fmt.Sscanf(r.URL.Query().Get("min_price"), "%f", &minPrice)
	fmt.Sscanf(r.URL.Query().Get("max_price"), "%f", &maxPrice)

	query := buildProductQuery(category, sortField, minPrice, maxPrice)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck endpoint for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
